"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import type {
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table";
import { Button } from "@ui/components/button";
import {
  AdminListPageHeader,
  AdminPageGuard,
  AdminPageLoading,
  AdminPageSection,
} from "@ui/components/admin";
import { ImageLightbox } from "@ui/components/image-lightbox";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs";
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell";
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client";
import type { DataTableUserSearchHandlers } from "@ui/components/data-table";
import { useAuth } from "@/providers/auth-provider";
import { api } from "@/lib/api";
import { normalizeAdminFilterValue } from "@/lib/build-admin-filter-query";
import { useDebouncedValue } from "@/hooks/use-debounced-value";

const UPLOAD_OWNER_FILTER_DEBOUNCE_MS = 400;
import {
  ArchiveRestore,
  Download,
  FileText,
  Image as ImageIcon,
  Loader2,
  Shuffle,
  Upload,
  Video,
  Music,
} from "lucide-react";
import {
  formatExtensionsSummary,
  getRealmDefaultExtensions,
} from "./_component/storage-upload-policy";
import {
  FileStorageCreateFolderButton,
  FileStorageDeleteFolderButton,
  FileStorageFolderNav,
  FileStorageGlobalEmpty,
  FileStorageImportConfirmDialogs,
  FileStorageMoveDialog,
  FileStorageReorganizeDialog,
  FileStorageTable,
  FileStorageUploadDialog,
  getFileStorageColumns,
  StorageVideoPreview,
  useFileStorageActions,
  useFileStorageList,
  type FileStorageRow,
  type StorageRealm,
} from "./_component";
import {
  isImageStorageRow,
  resolveStorageAssetUrl,
  resolveFolderPathAfterCreate,
} from "./_component/utils";

const REALM_ORDER: StorageRealm[] = ["images", "files", "videos", "audio"];

const REALM_ICONS: Record<StorageRealm, typeof ImageIcon> = {
  images: ImageIcon,
  files: FileText,
  videos: Video,
  audio: Music,
};

function FileStoragePageInner() {
  const { user } = useAuth();
  const canUpload = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_CREATE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false;
  const canDelete = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_DELETE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false;
  const canView = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_VIEW) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false;
  const canManage = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false;

  const [reorganizeOpen, setReorganizeOpen] = useState(false);
  const [moveDialogOpen, setMoveDialogOpen] = useState(false);
  const [moveRows, setMoveRows] = useState<FileStorageRow[]>([]);

  const [activeRealm, setActiveRealm] = useState<StorageRealm>("images");
  const [activeFolderPath, setActiveFolderPath] = useState("");
  const [includeDescendants, setIncludeDescendants] = useState(false);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [selectedRowIds, setSelectedRowIds] = useState<RowSelectionState>({});
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [videoPreviewRow, setVideoPreviewRow] = useState<FileStorageRow | null>(
    null,
  );
  const [folderRefreshKey, setFolderRefreshKey] = useState(0);

  const bumpFolderList = useCallback(() => {
    setFolderRefreshKey((key) => key + 1);
  }, []);

  const uploadOwnerFilter = useMemo(() => {
    const raw = columnFilters.find((f) => f.id === "uploadOwnerId")?.value;
    return normalizeAdminFilterValue(raw) ?? "";
  }, [columnFilters]);

  const debouncedUploadOwnerFilter = useDebouncedValue(
    uploadOwnerFilter,
    UPLOAD_OWNER_FILTER_DEBOUNCE_MS,
  );

  const { rows, realms, childFolders, breadcrumb, loading, isFetching, total, reload } =
    useFileStorageList(
      activeRealm,
      activeFolderPath,
      page,
      pageSize,
      includeDescendants,
      debouncedUploadOwnerFilter,
    );

  const totalInStorage = useMemo(
    () => realms.reduce((sum, realm) => sum + realm.count, 0),
    [realms],
  );

  const realmTabs = useMemo(() => {
    const byId = new Map(realms.map((r) => [r.id, r]));
    return REALM_ORDER.map((id) => {
      const fromApi = byId.get(id);
      return (
        fromApi ?? {
          id,
          label:
            id === "images"
              ? "Hình ảnh"
              : id === "files"
                ? "Tệp tin"
                : id === "videos"
                  ? "Video"
                  : "Âm thanh",
          count: 0,
        }
      );
    });
  }, [realms]);

  const {
    uploadDialogOpen,
    setUploadDialogOpen,
    setUploading,
    importInputRef,
    uploading,
    importing,
    deletingPath,
    downloadingPath,
    uploadAccept,
    handleImport,
    importConfirm,
    clearImportConfirm,
    handleImportConfirmRestore,
    handleImportConfirmOverwrite,
    handleImportSkipOverwrite,
    handleDownload,
    handleDownloadAll,
    handleBulkDownload,
    downloadingAll,
    handleDelete,
    handleBulkDelete,
    handleDeleteAllInTab,
    fetchAllRowsInScope,
    openUploadPicker,
    openImportPicker,
  } = useFileStorageActions({
    activeRealm,
    activeFolderPath,
    includeDescendants,
    uploadOwnerFilter: debouncedUploadOwnerFilter,
    reload,
  });

  const activeRealmMeta = realmTabs.find((r) => r.id === activeRealm);
  const currentFolderLabel =
    breadcrumb[breadcrumb.length - 1]?.label ??
    activeRealmMeta?.label ??
    activeRealm;
  const activeTabLabel = breadcrumb.length
    ? `${activeRealmMeta?.label ?? activeRealm} · ${breadcrumb.map((c) => c.label).join(" / ")}`
    : activeRealmMeta?.label;

  const realmUploadHint = useMemo(
    () => formatExtensionsSummary(getRealmDefaultExtensions(activeRealm)),
    [activeRealm],
  );

  const lightboxImages = useMemo(
    () =>
      rows
        .filter((r) => isImageStorageRow(r))
        .map((r) => ({
          key: r.relativePath,
          src: resolveStorageAssetUrl(r),
          altText: r.originalName,
        })),
    [rows],
  );

  const openImagePreview = useCallback(
    (row: FileStorageRow) => {
      const idx = lightboxImages.findIndex((li) => li.key === row.relativePath);
      if (idx >= 0) {
        setLightboxIndex(idx);
        setLightboxOpen(true);
      }
    },
    [lightboxImages],
  );

  const openVideoPreview = useCallback((row: FileStorageRow) => {
    setVideoPreviewRow(row);
  }, []);

  const handleRealmChange = useCallback((value: string) => {
    setActiveRealm(value as StorageRealm);
    setActiveFolderPath("");
    setColumnFilters([]);
    setPage(1);
    setSelectedRowIds({});
    bumpFolderList();
  }, [bumpFolderList]);

  const handleFolderNavigate = useCallback((folderPath: string) => {
    setActiveFolderPath(folderPath);
    setPage(1);
    setSelectedRowIds({});
  }, []);

  const handleFolderCreated = useCallback(
    async (folderPath: string) => {
      setActiveFolderPath(resolveFolderPathAfterCreate(folderPath, activeRealm));
      setPage(1);
      setSelectedRowIds({});
      bumpFolderList();
      await reload();
    },
    [activeRealm, bumpFolderList, reload],
  );

  const handleFolderDeleted = useCallback(async () => {
    const parentPath =
      breadcrumb.length >= 2
        ? breadcrumb[breadcrumb.length - 2].id
        : "";
    setActiveFolderPath(parentPath);
    setPage(1);
    setSelectedRowIds({});
    bumpFolderList();
    await reload();
  }, [breadcrumb, bumpFolderList, reload]);

  const handleBulkMove = useCallback((selected: FileStorageRow[]) => {
    setMoveRows(selected);
    setMoveDialogOpen(true);
  }, []);

  const handleMoveCompleted = useCallback(async () => {
    setSelectedRowIds({});
    await reload();
  }, [reload]);

  const handleMoveAllInScope = useCallback(async () => {
    const allRows = await fetchAllRowsInScope();
    if (!allRows.length) return;
    setMoveRows(allRows);
    setMoveDialogOpen(true);
  }, [fetchAllRowsInScope]);

  const handleIncludeDescendantsChange = useCallback((value: boolean) => {
    setIncludeDescendants(value);
    setPage(1);
    setSelectedRowIds({});
  }, []);

  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updater) => {
      setColumnFilters(updater);
    },
    [],
  );

  useEffect(() => {
    setPage(1);
    setSelectedRowIds({});
  }, [debouncedUploadOwnerFilter]);

  const handleClearFilters = useCallback(() => {
    setColumnFilters([]);
    setPage(1);
    setSelectedRowIds({});
  }, []);

  const uploadOwnerSearchHandlers = useMemo<DataTableUserSearchHandlers>(
    () => ({
      onSearch: async (q) => {
        const res = await api.users.list({ q, page: 1, limit: 10 });
        return res.items.map((user) => ({
          id: user.id,
          label: user.fullName?.trim() || user.email,
          sublabel: user.email,
        }));
      },
      onResolveUser: async (id) => {
        const user = await api.users.get(id);
        return {
          id: user.id,
          label: user.fullName?.trim() || user.email,
          sublabel: user.email,
        };
      },
    }),
    [],
  );

  const columns = useMemo(
    () =>
      getFileStorageColumns({
        canDelete,
        deletingPath,
        downloadingPath,
        onPreviewImage: openImagePreview,
        onPreviewVideo: openVideoPreview,
        onDownload: handleDownload,
        onDelete: handleDelete,
        uploadOwnerSearchHandlers,
      }),
    [
      canDelete,
      deletingPath,
      downloadingPath,
      handleDelete,
      handleDownload,
      openImagePreview,
      openVideoPreview,
      uploadOwnerSearchHandlers,
    ],
  );

  const wrappedBulkDelete = useCallback(
    async (selected: FileStorageRow[]) => {
      await handleBulkDelete(selected);
      setSelectedRowIds({});
    },
    [handleBulkDelete],
  );

  const tableProps = {
    data: rows,
    columns,
    isLoading: loading,
    isFetching,
    itemLabel: "file" as const,
    page,
    pageSize,
    total,
    onPageChange: setPage,
    onPageSizeChange: setPageSize,
    selectedRowIds,
    onSelectedRowIdsChange: setSelectedRowIds,
    onBulkDelete: wrappedBulkDelete,
    onBulkDownload: handleBulkDownload,
    onBulkMove: canManage ? handleBulkMove : undefined,
    onMoveAllInScope: canManage ? handleMoveAllInScope : undefined,
    onDeleteAllInTab: canDelete ? handleDeleteAllInTab : undefined,
    columnFilters,
    onColumnFiltersChange: handleColumnFiltersChange,
    onClearFilters: handleClearFilters,
    includeDescendants,
    canDelete,
    canUpload,
    uploading,
    onUpload: openUploadPicker,
  };

  return (
    <AdminPageSection>
      <AdminListPageHeader
        icon={ImageIcon}
        title="Kho lưu trữ file"
        subtitle="Điều hướng folder không giới hạn cấp. Di chuyển file giữa Hình ảnh / Tệp tin / Video. Tạo hoặc xóa folder theo phạm vi đang mở."
        actions={
          canUpload || canView ? (
            <div className="flex items-center gap-2">
              {canUpload ? (
                <>
                  <input
                    ref={importInputRef}
                    type="file"
                    accept=".zip,application/zip"
                    className="hidden"
                    onChange={(e) => void handleImport(e)}
                  />
                  <Button
                    type="button"
                    onClick={openUploadPicker}
                    disabled={uploading || importing || downloadingAll}
                  >
                    {uploading ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <Upload className="size-4" />
                    )}
                    {uploading ? "Đang tải…" : "Tải lên"}
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={openImportPicker}
                    disabled={uploading || importing || downloadingAll}
                  >
                    {importing ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <ArchiveRestore className="size-4" />
                    )}
                    {importing ? "Đang khôi phục…" : "Khôi phục kho"}
                  </Button>
                </>
              ) : null}
              {canManage ? (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setReorganizeOpen(true)}
                  disabled={downloadingAll || uploading || importing}
                >
                  <Shuffle className="size-4" />
                  Cấu trúc lại folder
                </Button>
              ) : null}
              {canView ? (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => void handleDownloadAll()}
                  disabled={downloadingAll || uploading || importing}
                >
                  {downloadingAll ? (
                    <Loader2 className="size-4 animate-spin" />
                  ) : (
                    <Download className="size-4" />
                  )}
                  {downloadingAll ? "Đang tải…" : "Tải về tất cả"}
                </Button>
              ) : null}
            </div>
          ) : undefined
        }
      />

      {loading && totalInStorage === 0 && realms.length === 0 ? (
        <AdminPageLoading variant="list" />
      ) : !loading && totalInStorage === 0 ? (
        <FileStorageGlobalEmpty
          canUpload={canUpload}
          uploading={uploading}
          importing={importing}
          onUpload={openUploadPicker}
          onImport={openImportPicker}
        />
      ) : (
        <Tabs value={activeRealm} onValueChange={handleRealmChange}>
          <div className="flex flex-wrap items-center gap-2">
            <TabsList className={`${ADMIN_LIST_TABS_LIST_CLASS} flex-wrap`}>
              {realmTabs.map((realm) => {
                const Icon = REALM_ICONS[realm.id as StorageRealm] ?? ImageIcon;
                return (
                  <TabsTrigger
                    key={realm.id}
                    value={realm.id}
                    className={ADMIN_LIST_TABS_TRIGGER_CLASS}
                  >
                    <Icon className="size-4" />
                    {realm.label}
                    <span className="text-muted-foreground">
                      ({realm.count})
                    </span>
                  </TabsTrigger>
                );
              })}
            </TabsList>
            <p className="w-full text-xs text-muted-foreground">
              Tab «{activeRealmMeta?.label ?? activeRealm}»: cho phép import{" "}
              {realmUploadHint}. Folder cấp 1 có thể tùy chỉnh khi tạo mới.
            </p>
          </div>

          {realmTabs.map((realm) => (
            <TabsContent key={realm.id} value={realm.id} className="space-y-4">
              {activeRealm === realm.id ? (
                <div className="space-y-4">
                  <FileStorageFolderNav
                    realm={activeRealm}
                    realmLabel={realm.label}
                    breadcrumb={breadcrumb}
                    childFolders={childFolders}
                    activeFolderPath={activeFolderPath}
                    includeDescendants={includeDescendants}
                    onIncludeDescendantsChange={handleIncludeDescendantsChange}
                    onNavigate={handleFolderNavigate}
                    foldersRefreshKey={folderRefreshKey}
                    actions={
                      <>
                        {canUpload ? (
                          <FileStorageCreateFolderButton
                            realm={activeRealm}
                            parentFolderPath={activeFolderPath}
                            parentLabel={currentFolderLabel}
                            onCreated={handleFolderCreated}
                            disabled={uploading || importing}
                          />
                        ) : null}
                        {canDelete && activeFolderPath ? (
                          <FileStorageDeleteFolderButton
                            realm={activeRealm}
                            folderPath={activeFolderPath}
                            folderLabel={currentFolderLabel}
                            onDeleted={handleFolderDeleted}
                            disabled={uploading || importing}
                          />
                        ) : null}
                      </>
                    }
                  />
                  <FileStorageTable
                    tableScope={`file-storage-${realm.id}-${activeFolderPath || "root"}`}
                    emptyLabel={
                      debouncedUploadOwnerFilter
                        ? "Không có file khớp bộ lọc người upload."
                        : `Chưa có file trong «${currentFolderLabel}».`
                    }
                    emptySummary={
                      debouncedUploadOwnerFilter
                        ? "Không có file khớp bộ lọc"
                        : `Không có file trong ${currentFolderLabel}`
                    }
                    tabLabel={currentFolderLabel}
                    {...tableProps}
                  />
                </div>
              ) : null}
            </TabsContent>
          ))}
        </Tabs>
      )}

      <ImageLightbox
        open={lightboxOpen}
        images={lightboxImages}
        index={lightboxIndex}
        onIndexChange={setLightboxIndex}
        onClose={() => setLightboxOpen(false)}
      />

      <StorageVideoPreview
        row={videoPreviewRow}
        open={videoPreviewRow != null}
        onClose={() => setVideoPreviewRow(null)}
      />

      {canManage ? (
        <FileStorageReorganizeDialog
          open={reorganizeOpen}
          onOpenChange={setReorganizeOpen}
          realm={activeRealm}
          activeFolderPath={activeFolderPath}
          scopeLabel={activeTabLabel ?? activeRealmMeta?.label ?? activeRealm}
          onCompleted={reload}
        />
      ) : null}

      {canManage ? (
        <FileStorageMoveDialog
          open={moveDialogOpen}
          onOpenChange={setMoveDialogOpen}
          selectedRows={moveRows}
          onMoved={handleMoveCompleted}
        />
      ) : null}

      {canUpload ? (
        <FileStorageImportConfirmDialogs
          state={importConfirm}
          importing={importing}
          onClose={clearImportConfirm}
          onConfirmRestore={handleImportConfirmRestore}
          onConfirmOverwrite={handleImportConfirmOverwrite}
          onSkipOverwrite={handleImportSkipOverwrite}
        />
      ) : null}

      {canUpload ? (
        <FileStorageUploadDialog
          open={uploadDialogOpen}
          onOpenChange={setUploadDialogOpen}
          activeRealm={activeRealm}
          activeFolderPath={activeFolderPath}
          activeTabLabel={activeTabLabel}
          uploadAccept={uploadAccept}
          onUploaded={reload}
          onUploadingChange={setUploading}
        />
      ) : null}
    </AdminPageSection>
  );
}

export default function FileStoragePage() {
  return (
    <AdminPageGuard permission="uploads:view">
      <FileStoragePageInner />
    </AdminPageGuard>
  );
}

src/app/file-storage/_component/columns..content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"

import { Badge } from "@ui/components/badge"

import { FileTypeIcon, FileTypeIconSm } from "@ui/components/file-type-icon"

import {
  defineDataTableActionsColumn,
  type DataTableUserSearchHandlers,
} from "@ui/components/data-table"

import { Film, Play } from "lucide-react"

import { formatAdminDateTime } from "@/lib/format-admin-datetime"

import { FileStorageRowActions } from "./file-row-actions"

import type { FileStorageRow } from "./types"

import {
  formatFileSize,
  formatUploadOwnerCell,
  isImageStorageRow,
  isVideoStorageRow,
  resolveStorageAssetUrl,
  storageThumbnailUrl,
} from "./utils"

export type FileStorageColumnsProps = {
  canDelete: boolean

  deletingPath: string | null

  downloadingPath: string | null

  onPreviewImage: (row: FileStorageRow) => void

  onPreviewVideo: (row: FileStorageRow) => void

  onDownload: (row: FileStorageRow) => void | Promise<void>

  onDelete: (row: FileStorageRow) => void | Promise<void>

  uploadOwnerSearchHandlers: DataTableUserSearchHandlers
}

export function getFileStorageColumns({
  canDelete,

  deletingPath,

  downloadingPath,

  onPreviewImage,

  onPreviewVideo,

  onDownload,

  onDelete,

  uploadOwnerSearchHandlers,
}: FileStorageColumnsProps): ColumnDef<FileStorageRow>[] {
  return [
    {
      id: "preview",

      header: "Xem trước",

      enableSorting: false,

      enableColumnFilter: false,

      size: 80,

      meta: { className: "w-[180px] min-w-[180px] max-w-[180px]" },

      cell: ({ row }) => {
        const item = row.original

        if (isImageStorageRow(item)) {
          return (
            <button
              type="button"
              onClick={() => onPreviewImage(item)}
              className="flex size-full cursor-pointer items-center justify-center overflow-hidden rounded-md border border-border bg-muted"
            >
              <img
                src={storageThumbnailUrl(item)}
                alt={item.originalName}
                className="size-full object-cover"
                loading="lazy"
                decoding="async"
              />
            </button>
          )
        }

        if (isVideoStorageRow(item)) {
          return (
            <button
              type="button"
              onClick={() => onPreviewVideo(item)}
              className="relative flex size-full cursor-pointer items-center justify-center overflow-hidden rounded-md border border-border bg-muted"
            >
              <Film className="size-8 text-muted-foreground" />

              <span className="absolute inset-0 flex items-center justify-center bg-black/25">
                <Play className="size-6 fill-white text-white" />
              </span>
            </button>
          )
        }

        return <FileTypeIcon filename={item.originalName} />
      },
    },

    {
      accessorKey: "originalName",

      header: "Tên file",

      enableSorting: false,

      enableColumnFilter: false,

      cell: ({ getValue, row }) => (
        <div className="flex min-w-0 items-center gap-2">
          <FileTypeIconSm filename={row.original.originalName} />

          <a
            href={resolveStorageAssetUrl(row.original)}
            target="_blank"
            rel="noopener noreferrer"
            className="truncate text-sm font-medium underline-offset-2 hover:underline"
            title={row.original.originalName}
          >
            {String(getValue())}
          </a>
        </div>
      ),
    },

    {
      accessorKey: "mediaKind",

      header: "Loại media",

      enableSorting: false,

      enableColumnFilter: false,

      size: 110,

      meta: { className: "w-[110px] min-w-[110px] max-w-[110px]" },

      cell: ({ row }) => {
        const kind = row.original.mediaKind

        const label =
          kind === "image"
            ? "Ảnh"
            : kind === "video"
              ? "Video"
              : kind === "audio"
                ? "Âm thanh"
                : kind === "document"
                  ? "Tài liệu"
                  : kind === "archive"
                    ? "Nén"
                    : "Khác"

        return (
          <Badge variant="secondary" className="text-[10px]">
            {label}
          </Badge>
        )
      },
    },

    {
      id: "uploadOwnerId",

      accessorFn: (row) => row.uploadOwnerId ?? "",

      header: "Người upload",

      enableSorting: false,

      enableColumnFilter: true,

      filterFn: () => true,

      size: 160,

      meta: {
        className: "w-[160px] min-w-[160px] max-w-[200px]",
        filterVariant: "user-search",
        filterLabel: "Người upload",
        filterPlaceholder: "Tên, email hoặc ID tài khoản…",
        userSearchHandlers: uploadOwnerSearchHandlers,
      },

      cell: ({ row }) => {
        const { primary, title } = formatUploadOwnerCell(row.original);
        if (primary === "—") {
          return (
            <span className="text-xs text-muted-foreground" title={title}>
              —
            </span>
          );
        }
        const id = row.original.uploadOwnerId?.trim();
        return (
          <div className="min-w-0 space-y-0.5" title={title}>
            <span className="block truncate text-xs font-medium text-foreground">
              {primary}
            </span>
            {id ? (
              <code className="block truncate text-[10px] text-muted-foreground">
                {id.length > 22 ? `${id.slice(0, 10)}…${id.slice(-6)}` : id}
              </code>
            ) : null}
          </div>
        );
      },
    },

    {
      accessorKey: "size",

      header: "Kích thước",

      enableSorting: false,

      enableColumnFilter: false,

      size: 120,

      meta: { className: "w-[120px] min-w-[120px] max-w-[120px]" },

      cell: ({ getValue }) => (
        <span className="text-sm text-muted-foreground tabular-nums">
          {formatFileSize(getValue() as number)}
        </span>
      ),
    },
    {
      accessorKey: "createdAt",

      header: "Ngày tải lên",

      enableSorting: false,

      enableColumnFilter: false,

      size: 180,

      meta: { className: "w-[180px] min-w-[180px] max-w-[180px]" },

      cell: ({ getValue }) => (
        <span className="text-xs text-muted-foreground tabular-nums">
          {formatAdminDateTime(getValue() as number | string)}
        </span>
      ),
    },

    defineDataTableActionsColumn<FileStorageRow>({
      cell: ({ row }) => (
        <FileStorageRowActions
          row={row.original}
          canDelete={canDelete}
          deleting={deletingPath === row.original.relativePath}
          downloading={downloadingPath === row.original.relativePath}
          onPreviewImage={
            isImageStorageRow(row.original)
              ? () => onPreviewImage(row.original)
              : undefined
          }
          onPreviewVideo={
            isVideoStorageRow(row.original)
              ? () => onPreviewVideo(row.original)
              : undefined
          }
          onDownload={() => onDownload(row.original)}
          onDelete={() => onDelete(row.original)}
        />
      ),
    }),
  ]
}

src/app/file-storage/_component/file-row.content:
"use client";

import {
  Download,
  ExternalLink,
  Eye,
  Film,
  Settings2,
  Trash2,
} from "lucide-react";
import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "@ui/components/data-table";
import type { FileStorageRow } from "./types";
import { resolveStorageAssetUrl } from "./utils";

export type FileStorageRowActionsProps = {
  row: FileStorageRow;
  canDelete: boolean;
  deleting?: boolean;
  downloading?: boolean;
  onPreviewImage?: () => void;
  onPreviewVideo?: () => void;
  onDownload: () => void | Promise<void>;
  onDelete: () => void | Promise<void>;
};

function deleteConfirm(row: FileStorageRow) {
  return {
    title: "Xóa file?",
    description: (
      <>
        File <strong>{row.originalName}</strong> sẽ bị xóa vĩnh viễn khỏi kho
        lưu trữ. Hành động này không thể hoàn tác.
      </>
    ),
    confirmLabel: "Xóa",
    destructive: true,
  };
}

export function FileStorageRowActions({
  row,
  canDelete,
  deleting,
  downloading,
  onPreviewImage,
  onPreviewVideo,
  onDownload,
  onDelete,
}: FileStorageRowActionsProps) {
  const actions: DataTableRowActionItem[] = [
    {
      key: "download",
      label: "Tải về",
      hint: "Lưu file xuống máy",
      onClick: onDownload,
      icon: <Download />,
      group: "primary",
      confirm: false,
    },
    {
      key: "open",
      label: "Mở tab mới",
      hint: "Xem file trong tab trình duyệt",
      onClick: () => {
        window.open(resolveStorageAssetUrl(row), "_blank", "noopener,noreferrer");
      },
      icon: <ExternalLink />,
      group: "primary",
      confirm: false,
    },
  ];

  if (onPreviewImage) {
    actions.unshift({
      key: "preview-image",
      label: "Xem ảnh",
      hint: "Mở lightbox xem ảnh",
      onClick: onPreviewImage,
      icon: <Eye />,
      group: "primary",
      confirm: false,
    });
  }

  if (onPreviewVideo) {
    actions.unshift({
      key: "preview-video",
      label: "Phát video",
      hint: "Xem trước video trong hộp thoại",
      onClick: onPreviewVideo,
      icon: <Film />,
      group: "primary",
      confirm: false,
    });
  }

  if (canDelete && !deleting) {
    actions.push({
      key: "delete",
      label: "Xóa",
      hint: "Xóa vĩnh viễn khỏi kho lưu trữ",
      onClick: onDelete,
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
      confirm: deleteConfirm(row),
    });
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={deleting || downloading}
      autoConfirmDangerousActions
      groups={{
        primary: { label: "Thao tác", icon: Settings2 },
        danger: { label: "Xóa", sublabel: true },
      }}
    />
  );
}

src/app/file-storage/_component/file-sto.content:
"use client";

import { Checkbox } from "@ui/components/checkbox";
import { Label } from "@ui/components/label";
import type { StorageRealm } from "./types";
import {
  extensionsFromGroupIds,
  formatExtensionsSummary,
  getRealmDefaultGroupIds,
  getRealmExtensionGroups,
  type StorageExtensionGroupId,
} from "./storage-upload-policy";

type FileStorageAllowedExtensionsPickerProps = {
  realm: StorageRealm;
  value: StorageExtensionGroupId[];
  onChange: (groupIds: StorageExtensionGroupId[]) => void;
  disabled?: boolean;
};

export function FileStorageAllowedExtensionsPicker({
  realm,
  value,
  onChange,
  disabled = false,
}: FileStorageAllowedExtensionsPickerProps) {
  const groups = getRealmExtensionGroups(realm);
  const selectedExtensions = extensionsFromGroupIds(realm, value);

  const toggleGroup = (groupId: StorageExtensionGroupId, checked: boolean) => {
    const next = checked
      ? [...new Set([...value, groupId])]
      : value.filter((id) => id !== groupId);
    onChange(
      next.length > 0 ? next : getRealmDefaultGroupIds(realm),
    );
  };

  return (
    <div className="space-y-2 rounded-lg border bg-muted/30 p-3">
      <div className="space-y-0.5">
        <p className="text-sm font-medium">Loại file được phép import</p>
        <p className="text-xs text-muted-foreground">
          Chỉ áp dụng cho folder cấp 1 mới. Folder con kế thừa cấu hình folder cha.
        </p>
      </div>
      <div className="space-y-2">
        {groups.map((group) => {
          const checked = value.includes(group.id);
          return (
            <div key={group.id} className="flex items-start gap-2">
              <Checkbox
                id={`ext-group-${group.id}`}
                checked={checked}
                disabled={disabled}
                onCheckedChange={(state) =>
                  toggleGroup(group.id, state === true)
                }
              />
              <div className="grid gap-0.5 leading-none">
                <Label
                  htmlFor={`ext-group-${group.id}`}
                  className="cursor-pointer text-sm font-normal"
                >
                  {group.label}
                </Label>
                <p className="text-xs text-muted-foreground">
                  {group.extensions.join(", ")}
                </p>
              </div>
            </div>
          );
        })}
      </div>
      <p className="text-xs text-muted-foreground">
        Đã chọn: {formatExtensionsSummary(selectedExtensions)}
      </p>
    </div>
  );
}

"use client";

import { useCallback, useMemo, useState } from "react";
import { Button } from "@ui/components/button";
import { Input } from "@ui/components/input";
import { Label } from "@ui/components/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@ui/components/popover";
import { toast } from "@ui/components/sonner";
import { resolveStorageFolderSlugPath } from "@workspace/api-client";
import { createStorageFolder } from "@/lib/admin-uploads";
import { FolderPlus, Loader2 } from "lucide-react";
import { FileStorageAllowedExtensionsPicker } from "./file-storage-allowed-extensions-picker";
import {
  extensionsFromGroupIds,
  getRealmDefaultGroupIds,
  type StorageExtensionGroupId,
} from "./storage-upload-policy";
import type { StorageRealm } from "./types";
import { resolveCreateFolderParent } from "./utils";

type FileStorageCreateFolderButtonProps = {
  realm: StorageRealm;
  parentFolderPath?: string;
  parentLabel: string;
  onCreated: (folderPath: string) => Promise<void>;
  disabled?: boolean;
  size?: "default" | "sm";
};

export function FileStorageCreateFolderButton({
  realm,
  parentFolderPath = "",
  parentLabel,
  onCreated,
  disabled = false,
  size = "sm",
}: FileStorageCreateFolderButtonProps) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [creating, setCreating] = useState(false);
  const [extensionGroups, setExtensionGroups] = useState<StorageExtensionGroupId[]>(
    () => getRealmDefaultGroupIds(realm),
  );
  const isLevel1Create = !parentFolderPath.trim();
  const slugPreview = useMemo(
    () => resolveStorageFolderSlugPath(name),
    [name],
  );

  const handleCreate = useCallback(async () => {
    const folderName = name.trim();
    if (!folderName) {
      toast.error("Vui lòng nhập tên thư mục");
      return;
    }

    const { parentPath, resourceType } = resolveCreateFolderParent(
      realm,
      parentFolderPath,
    );

    setCreating(true);
    try {
      const result = await createStorageFolder({
        folderName,
        parentPath,
        resourceType,
        allowedExtensions: isLevel1Create
          ? extensionsFromGroupIds(resourceType, extensionGroups)
          : undefined,
      });
      toast.success(
        `Đã tạo thư mục «${result.folderLabel ?? result.folderName}»`,
      );
      setName("");
      setOpen(false);
      await onCreated(result.folderPath);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Không tạo được thư mục");
    } finally {
      setCreating(false);
    }
  }, [
    extensionGroups,
    isLevel1Create,
    name,
    onCreated,
    parentFolderPath,
    realm,
  ]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger className="w-auto">
        <Button
          type="button"
          variant="outline"
          size={size}
          disabled={disabled || creating}
          className="shrink-0 gap-1.5"
        >
          {creating ? (
            <Loader2 className="size-4 animate-spin" />
          ) : (
            <FolderPlus className="size-4" />
          )}
          Tạo folder
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[min(100vw-2rem,22rem)] space-y-3" align="start">
        <div className="space-y-1">
          <p className="text-sm font-medium">Tạo thư mục mới</p>
          <p className="text-xs text-muted-foreground">
            Trong «{parentLabel}». Nhập tên tiếng Việt — hệ thống tự tạo slug
            cho đường dẫn (vd. Sự kiện 1 → su-kien-1).
          </p>
        </div>
        <div className="space-y-2">
          <Label htmlFor="create-folder-name">Tên hiển thị</Label>
          <Input
            id="create-folder-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="vd. Sự kiện 1, Avatars, 2026/06/Hội thảo"
            disabled={creating}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                void handleCreate();
              }
            }}
          />
          {slugPreview ? (
            <div className="rounded-md border border-border/70 bg-muted/20 px-2.5 py-2 text-xs">
              <p>
                <span className="text-muted-foreground">Nhãn: </span>
                <span className="font-medium text-foreground">
                  {slugPreview.leafLabel}
                </span>
              </p>
              <p className="mt-1 font-mono text-[11px] text-muted-foreground">
                slug: {slugPreview.slugPath}
              </p>
            </div>
          ) : null}
        </div>
        {isLevel1Create ? (
          <FileStorageAllowedExtensionsPicker
            realm={realm}
            value={extensionGroups}
            onChange={setExtensionGroups}
            disabled={creating}
          />
        ) : null}
        <div className="flex justify-end gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setOpen(false)}
            disabled={creating}
          >
            Hủy
          </Button>
          <Button
            type="button"
            size="sm"
            onClick={() => void handleCreate()}
            disabled={creating || !name.trim()}
          >
            {creating ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <FolderPlus className="size-4" />
            )}
            Tạo
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useCallback, useState } from "react";
import { Button } from "@ui/components/button";
import { ConfirmActionDialog } from "@ui/components/dialogs";
import { toast } from "@ui/components/sonner";
import { deleteStorageFolder } from "@/lib/admin-uploads";
import { FolderX, Loader2 } from "lucide-react";
import type { StorageRealm } from "./types";
import { resolveStorageFolderDiskPath } from "./utils";

type FileStorageDeleteFolderButtonProps = {
  realm: StorageRealm;
  folderPath: string;
  folderLabel: string;
  onDeleted: () => Promise<void>;
  disabled?: boolean;
};

export function FileStorageDeleteFolderButton({
  realm,
  folderPath,
  folderLabel,
  onDeleted,
  disabled = false,
}: FileStorageDeleteFolderButtonProps) {
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const diskPath = resolveStorageFolderDiskPath(realm, folderPath);

  const runDelete = useCallback(async () => {
    if (!diskPath) return;

    setDeleting(true);
    const pending = toast.loading("Đang xóa thư mục…");
    try {
      await deleteStorageFolder(diskPath);
      toast.success(`Đã xóa thư mục «${folderLabel}»`, { id: pending });
      setConfirmOpen(false);
      await onDeleted();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Không xóa được thư mục", {
        id: pending,
      });
    } finally {
      setDeleting(false);
    }
  }, [diskPath, folderLabel, onDeleted]);

  if (!diskPath) return null;

  return (
    <>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="gap-1.5 text-destructive hover:text-destructive"
        onClick={() => setConfirmOpen(true)}
        disabled={disabled || deleting}
      >
        {deleting ? (
          <Loader2 className="size-4 animate-spin" />
        ) : (
          <FolderX className="size-4" />
        )}
        Xóa folder
      </Button>

      <ConfirmActionDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title={`Xóa thư mục «${folderLabel}»?`}
        icon={<FolderX className="size-5 text-destructive" />}
        description={
          <>
            Toàn bộ file bên trong sẽ bị xóa vĩnh viễn.
            <br />
            <br />
            Đường dẫn:{" "}
            <span className="font-mono text-foreground">{diskPath}</span>
            <br />
            <br />
            Thao tác không thể hoàn tác.
          </>
        }
        confirmLabel="Xóa thư mục"
        cancelLabel="Huỷ"
        confirmDestructive
        confirmLoading={deleting}
        onConfirm={runDelete}
      />
    </>
  );
}

