  return (
    <AdminDataTable<GuideGroup>
      tableScope="guides"
      data={data}
      getRowId={(row) => String(row.id)}
      defaultExpandedAll={false}
      rowReorderEnabled={Boolean(onRowReorder)}
      onRowReorder={onRowReorder}
      mapReorderedRows={applyOrderToGroups}
      rowReorderDisabled={isReordering}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Chưa có nhóm hướng dẫn nào."
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo section key, tiêu đề..."
      onClearFilters={onClearFilters}
      onRowPointerEnter={
        onRowPrefetch
          ? (row) => onRowPrefetch(row.original)
