      }
      clearFiltersVariant="destructive"
      {...adminTableRowSelectionProps(selectedRowIds, setSelectedRowIds)}
      bulkActions={[
        {
          id: "bulk-guide-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          onAction: async (rows) => {
            await onBulkPurge(rows);
          },
        },
      ]}

