function NewLocationPageInner() {
  const crudNav = useAdminCrudNavigation("/locations");
  const queryClient = useQueryClient();
  const { form } = useLocationForm();

  const invalidateAll = async () => {
    await queryClient.invalidateQueries({ queryKey: ["locations"] });
  };

  const createMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: (_data, variables) => `Đã tạo địa điểm "${(variables.name as string)?.trim() || (variables.mapUrl as string)?.trim()}"`,
      error: (err) => err instanceof Error ? err.message : "Không thể tạo địa điểm",
