import type { UseMutationResult } from "@tanstack/react-query";

import type { StoreSyncSdk } from "@workspace/api-client";
import type { PostListRow } from "../types";

import { useAdminMutation } from "@/hooks/use-admin-mutation";
export interface UsePostsMutationsProps {
  api: StoreSyncSdk;
  invalidateAll: () => Promise<void>;
}

export function useDeleteMutation({
  api,
  invalidateAll,
}: UsePostsMutationsProps): UseMutationResult<unknown, Error, string, unknown> {
  return useAdminMutation({
    mutationFn: async (id: string) => api.posts.remove(id),
    onSuccess: invalidateAll,
  });
}

export function useRestoreMutation({
  api,
  invalidateAll,
}: UsePostsMutationsProps): UseMutationResult<PostListRow, Error, string, unknown> {
  return useAdminMutation({
    mutationFn: async (id: string) =>
      api.posts.restore<PostListRow>(id),
    onSuccess: invalidateAll,
  });
}

export function usePurgeMutation({
  api,
  invalidateAll,
}: UsePostsMutationsProps): UseMutationResult<unknown, Error, string, unknown> {
  return useAdminMutation({
    mutationFn: async (id: string) => api.posts.purge(id),
    onSuccess: invalidateAll,
  });
}

export function useBulkMutation({
  api,
  invalidateAll,
}: UsePostsMutationsProps): UseMutationResult<unknown, Error, { action: "delete" | "restore" | "hard-delete"; ids: string[] }, unknown> {
  return useAdminMutation({
    mutationFn: async (input: {
      action: "delete" | "restore" | "hard-delete";
      ids: string[];
    }) => api.posts.bulk(input),
    onSuccess: invalidateAll,
  });
}

import { adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@/lib/admin-detail-query";
import type { UseQueryResult } from "@tanstack/react-query";
import { useQuery, type QueryClient } from "@tanstack/react-query";
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client";
import type { PostDetail, PostListRow } from "../types";

function toFilterQuery(filters: Record<string, unknown>): Record<string, string | number | boolean | undefined | null> {
  return Object.fromEntries(
    Object.entries(filters).map(([key, value]) => [`filter[${key}]`, value as string | number | boolean | undefined | null]),
  );
}


export const postDetailQueryKey = (postId: string) =>
  ["media", "posts", "detail", postId] as const;

export function prefetchPostDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  postId: string
) {
  return prefetchAdminDetailQuery(
    queryClient,
    postDetailQueryKey(postId),
    () => api.posts.get<PostDetail>(postId)
  );
}

export function usePostDetailQuery(
  api: StoreSyncSdk,
  postId: string
) {
  return useQuery({
    ...adminDetailQueryOptions(
      postDetailQueryKey(postId),
      async () => api.posts.get<PostDetail>(postId),
      postId
    ),
});
}

export interface UsePostsQueriesProps {
  api: StoreSyncSdk;
  page: number;
  pageSize: number;
  debouncedQ: string;
  postColumnFilterQuery: Record<string, unknown>;
}

export function usePostsQuery({
  api,
  page,
  pageSize,
  debouncedQ,
  postColumnFilterQuery,
}: UsePostsQueriesProps): UseQueryResult<PagedResult<PostListRow>> {
  return useQuery({
    queryKey: ["media", "posts", "list", page, pageSize, debouncedQ, postColumnFilterQuery],
    queryFn: async (): Promise<PagedResult<PostListRow>> =>
      api.posts.list<PostListRow>({
        page,
        limit: pageSize,
        search: debouncedQ.trim() || undefined,
        status: "active",
        ...toFilterQuery(postColumnFilterQuery),
      }),
  });
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk;
  trashPage: number;
  trashPageSize: number;
  debouncedTrashQ: string;
  trashColumnFilterQuery?: Record<string, unknown>;
  enabled: boolean;
}

export function useTrashQuery({
  api,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  trashColumnFilterQuery,
  enabled,
}: UseTrashQueryProps): UseQueryResult<PagedResult<PostListRow>> {
  return useQuery({
    queryKey: ["media", "posts", "trash", trashPage, trashPageSize, debouncedTrashQ, trashColumnFilterQuery],
    enabled,
    queryFn: async (): Promise<PagedResult<PostListRow>> =>
      api.posts.list<PostListRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        ...toFilterQuery(trashColumnFilterQuery ?? {}),
      }),
  });
}

export interface UsePostsByAuthorProps {
  api: StoreSyncSdk;
  authorId: string;
  page?: number;
  limit?: number;
}

export function usePostsByAuthor({
  api,
  authorId,
  page = 1,
  limit = 5,
}: UsePostsByAuthorProps): UseQueryResult<PagedResult<PostListRow>> {
  return useQuery({
    queryKey: ["media", "posts", "by-author", authorId, page, limit],
    queryFn: async (): Promise<PagedResult<PostListRow>> =>
      api.posts.list<PostListRow>({
        page,
        limit,
        status: "active",
        ...toFilterQuery({ authorId }),
      }),
    enabled: !!authorId,
  });
}

src/app/posts/_component/_query/use-taxo.content:
import type { UseQueryResult } from "@tanstack/react-query";
import { useQuery } from "@tanstack/react-query";
import type { StoreSyncSdk } from "@workspace/api-client";
import type { CategoryTreeOption, TaxonomyOption } from "../types";

export function useCategoriesQuery(
  api: StoreSyncSdk
): UseQueryResult<CategoryTreeOption[]> {
  return useQuery({
    queryKey: ["categories", "options"],
    queryFn: async (): Promise<CategoryTreeOption[]> => {
      const paged = await api.categories.rawList<CategoryTreeOption>({
        page: 1,
        limit: 200,
        status: "active",
      });
      return paged.items.map((item) => ({
        id: String(item.id),
        name: item.name,
        parentId: item.parentId ?? null,
        sortOrder: item.sortOrder ?? 0,
      }));
    },
  });
}

export function useTagsQuery(api: StoreSyncSdk): UseQueryResult<TaxonomyOption[]> {
  return useQuery({
    queryKey: ["tags", "options"],
    queryFn: async (): Promise<TaxonomyOption[]> => {
      const paged = await api.tags.list<TaxonomyOption>({
        page: 1,
        limit: 200,
        status: "active",
      });
      return paged.items;
    },
  });
}

