"use client"

import { useEffect } from "react"
import Image from "next/image"
import { useParams } from "next/navigation"
import { Package } from "lucide-react"
import { toast } from "@ui/components/sonner"
import { Badge } from "@ui/components/badge"
import {
  AdminDetailLayout,
  AdminDetailMain,
  AdminDetailPageHeader,
  AdminDetailSidebar,
  AdminPageGuard,
  AdminPageLoading,
  AdminPageSection,
} from "@ui/components/admin"
import {
  FieldSectionField,
  FieldSet,
  FieldSetContent,
  FieldSectionLegend,
} from "@ui/components/field"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { useAuth } from "@/providers/auth-provider"
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client"
import { api } from "@/lib/api"
import { useProductDetailQuery } from "../_component"

function formatVnd(n: number) {
  return new Intl.NumberFormat("vi-VN").format(n) + " ₫"
}

function ProductDetailInner() {
  const crudNav = useAdminCrudNavigation("/products")
  const params = useParams()
  const id = params.id as string
  const { user } = useAuth()
  const canUpdate = user
    ? canUserAccess(user, PERMISSION_CODES.PRODUCTS_UPDATE)
    : false
  const { data: product, isLoading, isError } = useProductDetailQuery(api, id)

  useEffect(() => {
    if (isError) {
      toast.error("Không tải được sản phẩm")
      crudNav.list()
    }
  }, [isError, crudNav])

  if (isLoading) return <AdminPageLoading />
  if (!product) return null

  const image = product.images?.[0]

  return (
    <AdminPageSection>
      <AdminDetailPageHeader
        title={product.name}
        subtitle={<span className="font-mono text-sm">{product.sku}</span>}
        onBack={() => crudNav.list()}
        onEdit={canUpdate ? () => crudNav.edit(id) : undefined}
      />
      <AdminDetailLayout>
        <AdminDetailMain>
          <FieldSet variant="section">
            <FieldSectionLegend icon={Package} title="Thông tin" />
            <FieldSetContent variant="section" className="grid gap-4 sm:grid-cols-2">
              <FieldSectionField label="Danh mục">{product.category}</FieldSectionField>
              <FieldSectionField label="Tồn kho">{product.stock}</FieldSectionField>
              <FieldSectionField label="Giá bán">
                {formatVnd(product.retailPrice)}
              </FieldSectionField>
              <FieldSectionField label="Giá KM">
                {formatVnd(product.wholesalePrice)}
              </FieldSectionField>
              <FieldSectionField label="Đơn vị">{product.unit}</FieldSectionField>
              <FieldSectionField label="Trạng thái">
                <Badge variant={product.isActive ? "default" : "secondary"}>
                  {product.isActive ? "Đang bán" : "Ẩn"}
                </Badge>
              </FieldSectionField>
              {product.description ? (
                <FieldSectionField label="Mô tả" className="sm:col-span-2">
                  {product.description}
                </FieldSectionField>
              ) : null}
            </FieldSetContent>
          </FieldSet>

          {product.unitTypes && product.unitTypes.length > 0 ? (
            <FieldSet variant="section">
              <FieldSectionLegend title="Loại hàng" />
              <FieldSetContent variant="section" className="space-y-3 pt-0">
                {product.unitTypes.map((unit) => (
                  <div key={unit.type} className="rounded-lg border p-3 text-sm">
                    <p className="font-medium">
                      {unit.label}{" "}
                      <span className="font-mono text-xs text-muted-foreground">
                        ({unit.type})
                      </span>
                    </p>
                    <p className="text-muted-foreground">
                      {unit.sku ? `${unit.sku} · ` : ""}
                      {formatVnd(unit.retailPrice)}
                      {unit.stock !== undefined ? ` · Tồn ${unit.stock}` : ""}
                    </p>
                    {unit.giftRules?.[0] ? (
                      <p className="mt-1 text-xs text-primary">
                        Quà: {unit.giftRules[0].label} (từ SL{" "}
                        {unit.giftRules[0].trigger.minQty ?? "—"})
                      </p>
                    ) : null}
                  </div>
                ))}
              </FieldSetContent>
            </FieldSet>
          ) : null}
        </AdminDetailMain>
        <AdminDetailSidebar>
          {image ? (
            <div className="relative aspect-square overflow-hidden rounded-lg border">
              <Image src={image} alt={product.name} fill className="object-cover" unoptimized />
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">Chưa có ảnh</p>
          )}
        </AdminDetailSidebar>
      </AdminDetailLayout>
    </AdminPageSection>
  )
}

export default function ProductDetailPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <ProductDetailInner />
    </AdminPageGuard>
  )
}

src/app/products/_component/columns.tsx.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { Badge } from "@ui/components/badge"
import {
  defineAdminCrudActionsColumn,
  defineAdminTrashActionsColumn,
} from "@ui/components/admin"
import type { AdminCrudRowHandlers } from "@/lib/admin-row-action-handlers"
import {
  buildAdminTableColumns,
  defineAdminCreatedAtColumn,
  defineAdminUpdatedAtColumn,
  type AdminTableView,
} from "@/lib/admin-table-columns"
import type { ProductRow } from "./types"

function formatVnd(value: number): string {
  return new Intl.NumberFormat("vi-VN").format(value) + " ₫"
}

export function getProductColumns({
  view = "list",
  openDetail = () => {},
  openEdit = () => {},
  rowActions,
  canWrite,
  canDelete,
  canRestore,
  canHardDelete,
}: {
  view?: AdminTableView
  openDetail?: (row: ProductRow) => void
  openEdit?: (row: ProductRow) => void
  rowActions: AdminCrudRowHandlers<ProductRow>
  canWrite: boolean
  canDelete?: boolean
  canRestore?: boolean
  canHardDelete?: boolean
}): ColumnDef<ProductRow>[] {
  const dataColumns: ColumnDef<ProductRow>[] = [
    {
      accessorKey: "sku",
      header: "SKU",
      meta: { filterPlaceholder: "Lọc SKU…" },
    },
    {
      accessorKey: "name",
      header: "Tên",
      meta: { filterPlaceholder: "Lọc tên…" },
      cell: ({ row, getValue }) => (
        <button
          type="button"
          className="text-left font-medium text-foreground transition-colors hover:text-primary"
          onClick={() => openDetail(row.original)}
        >
          {String(getValue())}
        </button>
      ),
    },
    {
      accessorKey: "category",
      header: "Danh mục",
    },
    {
      accessorKey: "retailPrice",
      header: "Giá bán",
      cell: ({ getValue }) => formatVnd(Number(getValue()) || 0),
    },
    {
      accessorKey: "stock",
      header: "Tồn",
      cell: ({ getValue }) => {
        const n = Number(getValue()) || 0
        return (
          <Badge variant={n <= 0 ? "destructive" : n < 10 ? "secondary" : "outline"}>
            {n}
          </Badge>
        )
      },
    },
    {
      accessorKey: "isActive",
      header: "Bán",
      cell: ({ getValue }) => (
        <Badge variant={getValue() ? "default" : "secondary"}>
          {getValue() ? "Đang bán" : "Ẩn"}
        </Badge>
      ),
    },
    defineAdminCreatedAtColumn<ProductRow>({ defaultHidden: true }),
    defineAdminUpdatedAtColumn<ProductRow>({ header: "Cập nhật" }),
  ]

  return buildAdminTableColumns({
    view,
    dataColumns,
    listActionsColumn: defineAdminCrudActionsColumn<ProductRow>({
      canWrite,
      canDelete,
      canHardDelete,
      onView: openDetail,
      onEdit: canWrite ? openEdit : undefined,
      onSoftDelete: rowActions.onSoftDelete,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
    trashActionsColumn: defineAdminTrashActionsColumn<ProductRow>({
      canWrite,
      canRestore,
      canHardDelete,
      onRestore: rowActions.onRestore,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
  })
}

src/app/products/_component/products-tab.content:
"use client"

import type { ColumnDef, ColumnFiltersState, OnChangeFn, RowSelectionState } from "@tanstack/react-table"
import { AdminDataTable, adminTableRowSelectionProps } from "@ui/components/data-table"
import type { ProductRow } from "./types"

export function ProductsTable({
  data,
  columns,
  isLoading,
  total,
  page,
  pageSize,
  onPageChange,
  onPageSizeChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  onClearFilters,
  onBulkDelete,
  onRowPrefetch,
}: {
  data: ProductRow[]
  columns: ColumnDef<ProductRow>[]
  isLoading: boolean
  total: number
  page: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  columnFilters?: ColumnFiltersState
  onColumnFiltersChange?: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  onClearFilters: () => void
  onBulkDelete?: (rows: ProductRow[]) => Promise<void>
  onRowPrefetch?: (row: ProductRow) => void
}) {
  return (
    <AdminDataTable<ProductRow>
      tableScope="products"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel='Chưa có sản phẩm — bấm "Thêm sản phẩm".'
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      onClearFilters={onClearFilters}
      pagination={{
        mode: "server",
        page,
        pageSize,
        total,
        onPageChange,
        onPageSizeChange,
      }}
      onRowPointerEnter={
        onRowPrefetch ? (row) => onRowPrefetch(row.original) : undefined
      }
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={
        onBulkDelete
          ? [
              {
                id: "bulk-product-delete",
                label: "Xóa tạm đã chọn",
                variant: "destructive" as const,
                confirm: {
                  title: "Đưa các sản phẩm đã chọn vào thùng rác?",
                  description: (rows: ProductRow[]) =>
                    `Bạn đã chọn ${rows.length} sản phẩm.`,
                  confirmLabel: "Xóa tạm",
                  destructive: true,
                },
                onAction: onBulkDelete,
              },
            ]
          : undefined
      }
    />
  )
}

src/app/products/_component/use-products.content:
import { adminDetailQueryOptions, prefetchAdminDetailQuery } from "@/lib/admin-detail-query"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk } from "@workspace/api-client"
import { mapProductRow, type ProductRow } from "./types"

export const productDetailQueryKey = (id: string) =>
  ["products", "detail", id] as const

export function prefetchProductDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  id: string,
) {
  return prefetchAdminDetailQuery(queryClient, productDetailQueryKey(id), () =>
    api.products.get(Number(id)),
  )
}

export function useProductDetailQuery(api: StoreSyncSdk, id: string) {
  return useQuery({
    ...adminDetailQueryOptions(
      productDetailQueryKey(id),
      async () => api.products.get(Number(id)),
      id,
    ),
  })
}

export function useProductsListQuery(
  api: StoreSyncSdk,
  params: {
    page: number
    limit: number
    q?: string
    status?: "active" | "deleted"
    enabled?: boolean
  },
) {
  return useQuery({
    queryKey: ["products", "list", params],
    queryFn: async () => {
      const result = await api.products.list({
        page: params.page,
        limit: params.limit,
        q: params.q,
        status: params.status === "deleted" ? "deleted" : "active",
      })
      return {
        items: result.items.map(mapProductRow),
        total: result.total,
      }
    },
    enabled: params.enabled !== false,
  })
}

export function useProductsTrashQuery(
  api: StoreSyncSdk,
  params: { page: number; limit: number; q?: string; enabled: boolean },
) {
  return useProductsListQuery(api, {
    ...params,
    status: "deleted",
  })
}

export type { ProductRow }

src/app/profile/page.tsx.content:
"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { toast } from "@ui/components/sonner"
import {
  Field,
  FieldContent,
  FieldLabel,
  FieldSet,
  FieldSetContent,
  FieldSectionField,
  FieldSectionLegend,
} from "@ui/components/field"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { Textarea } from "@ui/components/textarea"
import {
  Camera,
  KeyRound,
  Loader2,
  MapPin,
  Save,
} from "lucide-react"
import { useAuth } from "@/providers/auth-provider"

import {
  useChangeStaffPassword,
  useStaffProfile,
  useUpdateStaffProfile,
} from "@/hooks/queries"
import { patchAdminSessionProfile } from "@/lib/auth-session"
import { AdminListPageHeader, AdminPageGuard, AdminPageSection } from "@ui/components/admin"

function getRoleCode(role: { code?: string; name?: string }) {
  return role.code ?? role.name ?? ""
}

function formatDateTime(value?: string | null) {
  if (!value) return "Chưa có dữ liệu"
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString("vi-VN")
}

const PROFILE_FIELD_CLASS =
  "h-10 rounded-lg border-border/70 bg-background/70 px-3 shadow-inner"

const PROFILE_TEXTAREA_CLASS =
  "min-h-28 rounded-lg border-border/70 bg-background/70 px-3 py-2.5 shadow-inner"

const PROFILE_ACTION_BAR_CLASS =
  "flex justify-end border-t border-border/60 pt-4"

function AdminProfilePageInner() {
  const { user: sessionUser } = useAuth()
  const userId = sessionUser?.id
  const { data: profile, isLoading, isError, error } = useStaffProfile(userId)
  const updateProfile = useUpdateStaffProfile()
  const changePw = useChangeStaffPassword()

  const [fullName, setFullName] = useState("")
  const [phone, setPhone] = useState("")
  const [address, setAddress] = useState("")
  const [avatar, setAvatar] = useState("")
  const [uploadingAvatar, setUploadingAvatar] = useState(false)
  const avatarInputRef = useRef<HTMLInputElement>(null)
  const [currentPassword, setCurrentPassword] = useState("")
  const [newPassword, setNewPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const roles = useMemo(
    () => profile?.roles ?? sessionUser?.roles ?? [],
    [profile?.roles, sessionUser?.roles]
  )
  const email = profile?.email ?? sessionUser?.email ?? ""
  const isStudent = roles.some(
    (r) => getRoleCode(r).trim().toLowerCase() === "student"
  )
  const canChangeAvatar = !isStudent || !avatar

  useEffect(() => {
    if (!profile) return
    setFullName(profile.fullName ?? "")
    setPhone(profile.phone ?? "")
    setAddress(profile.address ?? "")
    setAvatar(profile.avatar ?? "")
  }, [profile])

  function initials(name: string): string {
    const parts = name.trim().split(/\s+/).filter(Boolean)
    if (parts.length === 0) return "?"
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
    return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
  }

  const handleUploadAvatar = async (file: File) => {
    if (!userId) return
    setUploadingAvatar(true)
    try {
      const { uploadAdminImage } = await import("@/lib/admin-upload")
      const url = await uploadAdminImage(file, {
        folderPath: "avatars",
        ownerUserId: userId,
      })
      setAvatar(url)
      toast.success("Đã tải ảnh đại diện")
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Lỗi upload ảnh")
    } finally {
      setUploadingAvatar(false)
    }
  }

  const handleSaveProfile = async () => {
    if (!userId) return
    const name = fullName.trim()
    if (!name) {
      toast.error("Vui lòng nhập họ tên")
      return
    }
    try {
      const u = await updateProfile.mutateAsync({
        id: userId,
        input: {
          fullName: name,
          phone: phone.trim() || undefined,
          address: address.trim() || undefined,
          avatar: avatar.trim() || null,
        },
      })
      patchAdminSessionProfile({
        name: u.fullName,
        phone: u.phone,
        address: u.address,
        image: u.avatar,
        updatedAt: u.updatedAt,
      })
    } catch {
      /* toast: MutationCache */
    }
  }

  const handleChangePassword = async () => {
    if (!userId) return
    if (!currentPassword) {
      toast.error("Nhập mật khẩu hiện tại")
      return
    }
    if (newPassword.length < 6) {
      toast.error("Mật khẩu mới tối thiểu 6 ký tự")
      return
    }
    if (newPassword !== confirmPassword) {
      toast.error("Nhập lại mật khẩu mới không khớp")
      return
    }
    try {
      await changePw.mutateAsync({
        id: userId,
        input: {
          currentPassword,
          newPassword,
        },
      })
      setCurrentPassword("")
      setNewPassword("")
      setConfirmPassword("")
    } catch {
      /* toast: MutationCache */
    }
  }

  if (!sessionUser) {
    return null
  }

  return (
    <AdminPageSection>
      <AdminListPageHeader
        title="Hồ sơ tài khoản"
        subtitle="Cập nhật tên, liên hệ, địa chỉ làm việc và mật khẩu đăng nhập admin."
      />

      {isError && (
        <p className="text-sm text-destructive">
          {error instanceof Error ? error.message : "Không tải được hồ sơ"}
        </p>
      )}

      <div className="grid gap-6 xl:grid-cols-[minmax(0,1.20fr)_minmax(0,0.80fr)]">
        <div className="space-y-6">
          <FieldSet variant="section">
            <FieldSectionLegend
              icon={MapPin}
              title="Thông tin liên hệ & địa chỉ"
              description="Cập nhật thông tin liên hệ để đồng bộ cho hồ sơ quản trị và các màn nội bộ liên quan."
            />
            <FieldSetContent variant="section" className="space-y-5">
              <div className="flex items-start gap-4">
                <div className="flex flex-col gap-2.5">
                  <div className="relative aspect-[3/4] w-40 sm:w-60 shrink-0">
                    {avatar ? (
                      <img
                        src={avatar}
                        alt="Avatar"
                        className="h-full w-full rounded-lg border-2 border-border/60 object-cover shadow-sm"
                      />
                    ) : (
                      <div className="flex h-full w-full items-center justify-center rounded-lg border-2 border-border/60 bg-muted text-lg font-bold text-muted-foreground">
                        {fullName ? initials(fullName) : "?"}
                      </div>
                    )}
                    <button
                      type="button"
                      onClick={() => avatarInputRef.current?.click()}
                      disabled={uploadingAvatar || !canChangeAvatar}
                      className="absolute -right-1 -bottom-1 flex size-7 items-center justify-center rounded-full border border-border bg-background shadow-sm hover:bg-accent disabled:opacity-50"
                      title="Tải ảnh đại diện"
                    >
                      <Camera className="size-3.5 text-muted-foreground" />
                    </button>
                    <input
                      ref={avatarInputRef}
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={(e) => {
                        const file = e.target.files?.[0]
                        if (file) void handleUploadAvatar(file)
                      }}
                    />
                  </div>
                  {profile && (
                    <div className="flex w-full flex-col gap-2.5">
                      <div className="rounded-lg border border-border/60 bg-muted/20 p-3">
                        <p className="text-xs tracking-wide text-muted-foreground uppercase">
                          Trạng thái
                        </p>
                        <p className="mt-1 text-sm font-semibold">
                          {profile.isActive ? "Đang hoạt động" : "Đã khoá"}
                        </p>
                      </div>
                      <div className="rounded-lg border border-border/60 bg-muted/20 p-3">
                        <p className="text-xs tracking-wide text-muted-foreground uppercase">
                          Cập nhật lần cuối
                        </p>
                        <p className="mt-1 truncate text-sm font-medium">
                          {formatDateTime(profile.updatedAt)}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
                <div className="flex w-full flex-col gap-2.5">
                  <div className="min-w-0 flex-1 space-y-1">
                    <Label htmlFor="admin-avatar-url">URL ảnh đại diện</Label>
                    <Input
                      id="admin-avatar-url"
                      value={avatar}
                      onChange={(e) => setAvatar(e.target.value)}
                      disabled={isLoading || !profile || !canChangeAvatar}
                      placeholder="https://example.com/avatar.jpg"
                      className={PROFILE_FIELD_CLASS}
                    />
                   {isStudent && avatar && (
                    <div className="mt-2 flex items-start gap-1.5 rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 shrink-0"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                      <span>
                        Bạn chỉ được tải ảnh đại diện{" "}
                        <strong>một lần duy nhất</strong>.
                      </span>
                    </div>
                  )}
                    {isStudent && !avatar && (
                      <div className="mt-2 flex items-start gap-1.5 rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="14"
                          height="14"
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth={2}
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          className="mt-0.5 shrink-0"
                        >
                          <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
                          <line x1="12" y1="9" x2="12" y2="13" />
                          <line x1="12" y1="17" x2="12.01" y2="17" />
                        </svg>
                        <span>
                          <strong>Cảnh báo:</strong> bạn chỉ được tải ảnh đại
                          diện <strong>một lần duy nhất</strong>. Hãy chọn ảnh
                          phù hợp trước khi tải lên.
                        </span>
                      </div>
                    )}
                  </div>
                  <FieldSectionField label="Email">
                    <span className="font-mono text-sm">{email}</span>
                  </FieldSectionField>
                  <p className="text-xs leading-relaxed text-muted-foreground -mt-3">
                    Email đăng nhập đang được quản trị tập trung từ hệ thống
                    và không chỉnh trực tiếp ở màn này.
                  </p>
                  <Field>
                    <FieldLabel htmlFor="admin-fullName">Họ và tên</FieldLabel>
                    <FieldContent>
                      <Input
                        id="admin-fullName"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value)}
                        disabled={isLoading || !profile}
                        className={PROFILE_FIELD_CLASS}
                      />
                    </FieldContent>
                  </Field>
                  <Field>
                    <FieldLabel htmlFor="admin-phone">Số điện thoại</FieldLabel>
                    <FieldContent>
                      <Input
                        id="admin-phone"
                        type="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        disabled={isLoading || !profile}
                        placeholder="VD: 0901234567"
                        className={PROFILE_FIELD_CLASS}
                      />
                    </FieldContent>
                  </Field>
                  <Field>
                    <FieldLabel htmlFor="admin-address">Địa chỉ / văn phòng</FieldLabel>
                    <FieldContent>
                      <Textarea
                        id="admin-address"
                        value={address}
                        onChange={(e) => setAddress(e.target.value)}
                        disabled={isLoading || !profile}
                        placeholder="Địa chỉ liên hệ khi cần (không bắt buộc)"
                        className={PROFILE_TEXTAREA_CLASS}
                      />
                    </FieldContent>
                  </Field>
                  <div className={PROFILE_ACTION_BAR_CLASS}>
                    <Button
                      type="button"
                      className="min-w-32 rounded-lg"
                      onClick={() => void handleSaveProfile()}
                      disabled={
                        isLoading || !profile || updateProfile.isPending
                      }
                    >
                      {updateProfile.isPending ? (
                        <Loader2 className="size-4 animate-spin" />
                      ) : (
                        <Save className="size-4" />
                      )}
                      <span className="ml-2">Lưu hồ sơ</span>
                    </Button>
                  </div>
                </div>
              </div>
            </FieldSetContent>
          </FieldSet>
        </div>
        <div className="space-y-6">
        <FieldSet variant="section">
            <FieldSectionLegend
              icon={KeyRound}
              title="Đổi mật khẩu"
              description="Đặt lại mật khẩu cho phiên đăng nhập quản trị. Mật khẩu mới cần từ 6 ký tự trở lên."
            />
            <FieldSetContent variant="section" className="space-y-5">
              <Field>
                <FieldLabel htmlFor="admin-current-pw">Mật khẩu hiện tại</FieldLabel>
                <FieldContent>
                  <Input
                    id="admin-current-pw"
                    type="password"
                    autoComplete="current-password"
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    placeholder="Nhập mật khẩu hiện tại"
                    className={PROFILE_FIELD_CLASS}
                  />
                </FieldContent>
              </Field>
