  return (<AdminPageSection><ScreenFormShell form={form} onSubmit={h} submitting={mut.isPending} editingId={id} cameraOptions={cameraOptions} templateOptions={templateOptions} onBack={() => crudNav.view(String(id))} onReset={async () => { await refetch(); }} /></AdminPageSection>);
