interface StaffTrashTableProps {
  data: StaffRow[]
  isLoading: boolean
  total: number
  page: number
  pageSize: number
  appliedPage?: number
  appliedPageSize?: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
