  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  onRestore: (user: StaffRow) => void
  onPurge: (user: StaffRow) => void
  busy: boolean
  canRestore: boolean
  canHardDelete: boolean
  onBulkRestore: (ids: string[]) => void
  onBulkPurge: (ids: string[]) => void
  onClearFilters: () => void
  listParams: {
    q?: string
    filters?: Record<string, string>
  }
}

export function StaffTrashTable(props: StaffTrashTableProps) {
  const {
    data,
    isLoading,
    total,
    page,
    pageSize,
    appliedPage,
    appliedPageSize,
    onPageChange,
    onPageSizeChange,
    columnFilters,
    onColumnFiltersChange,
    globalFilter,
    onGlobalFilterChange,
    selectedRowIds,
    onSelectedRowIdsChange,
    onRestore,
    onPurge,
    busy,
    canRestore: canRestorePerm,
    canHardDelete: canHardDeletePerm,
    onBulkRestore,
    onBulkPurge,
    onClearFilters,
    listParams,
  } = props

  const canWriteTrash = canRestorePerm || canHardDeletePerm

  const columns = getStaffColumns({
    view: "trash",
    onView: () => {},
    onEdit: () => {},
    onDelete: () => {},
    onRestore,
    onPurge,
    onToggleActive: () => {},
    busy,
    isProtected: () => false,
    canWrite: canWriteTrash,
    canRestore: canRestorePerm,
    canHardDelete: canHardDeletePerm,
