  openEdit?: (row: TrainingLevelRow) => void
  rowActions: AdminCrudRowHandlers<TrainingLevelRow>
  canWrite: boolean
  canDelete?: boolean
  canRestore?: boolean
  canHardDelete?: boolean
}): ColumnDef<TrainingLevelRow>[] {
