              `Bạn đã chọn ${rows.length} hệ đào tạo. Hành động này không thể hoàn tác.`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      pagination={{
        page,
        pageSize,
        total,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có hệ đào tạo trong thùng rác",
        itemLabel: "hệ đào tạo",
      }}
    />
  )
}

