 */
export function createAdminTrashExportFetchPage<T>(
  fetchList: (params: {
    page: number
    limit: number
    search?: string
    status: "deleted"
    [key: string]: string | number | undefined
  }) => Promise<{ items: T[]; total: number }>,
  exportParams: AdminTrashExportParams
) {
