"use client"

import { useCallback, useEffect, useState } from "react"
import Image from "next/image"
import { Loader2 } from "lucide-react"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog"
import { Button } from "@ui/components/button"
import { fetchImages } from "@/lib/admin-uploads"
import { resolveStorageAssetUrl } from "@/app/file-storage/_component/utils"
import type { ImageItem } from "@workspace/api-client"

export function StorageImagePickerDialog({
  open,
  onOpenChange,
  onSelect,
  title = "Chọn ảnh từ kho lưu trữ",
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (urls: string[]) => void
  title?: string
}) {
  const [items, setItems] = useState<ImageItem[]>([])
  const [loading, setLoading] = useState(false)
  const [page, setPage] = useState(1)
  const [total, setTotal] = useState(0)
  const pageSize = 24

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const data = await fetchImages(page, pageSize, {
        realm: "images",
        includeDescendants: true,
      })
      setItems(data.data)
      setTotal(data.pagination.total)
    } finally {
      setLoading(false)
    }
  }, [page])

  useEffect(() => {
    if (open) void load()
  }, [open, load])

  const maxPage = Math.max(1, Math.ceil(total / pageSize))

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
        </DialogHeader>
        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="size-8 animate-spin text-muted-foreground" />
          </div>
        ) : (
          <>
            <div className="grid grid-cols-3 gap-2 sm:grid-cols-4">
              {items.map((row) => {
                const url = resolveStorageAssetUrl(row)
                return (
                  <button
                    key={row.relativePath}
                    type="button"
                    className="relative aspect-square overflow-hidden rounded-md border hover:ring-2 hover:ring-primary"
                    onClick={() => {
                      onSelect([url])
                      onOpenChange(false)
                    }}
                  >
                    <Image
                      src={url}
                      alt={row.originalName ?? row.relativePath}
                      fill
                      className="object-cover"
                      unoptimized
                    />
                  </button>
                )
              })}
            </div>
            {items.length === 0 ? (
              <p className="py-8 text-center text-sm text-muted-foreground">
                Chưa có ảnh trong kho — upload tại File storage.
              </p>
            ) : null}
            <div className="flex items-center justify-between pt-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
              >
                Trước
              </Button>
              <span className="text-xs text-muted-foreground">
                Trang {page}/{maxPage}
              </span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={page >= maxPage}
                onClick={() => setPage((p) => p + 1)}
              >
                Sau
              </Button>
            </div>
          </>
        )}
      </DialogContent>
    </Dialog>
  )
}

