/** Kết nối socket admin — invalidate cache React Query khi có mutation từ tab/user khác. */
export function AdminRealtimeSync() {
  const { user } = useAuth()
  const queryClient = useQueryClient()
  useAdminRealtimeSync(!!user, queryClient)
  return null
}

