"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import { useRouter } from "next/navigation";
import type { AuthUser } from "@workspace/api-client";
import { canAccessStaffAdmin } from "@workspace/api-client";
import {
  loginWithDevelopmentUser,
  loginWithEmail,
  loginWithGoogle,
  toAdminSessionUser,
} from "@/features/auth/auth-api";
import {
  ADMIN_SESSION_EVENT,
  ADMIN_SESSION_KEY,
  clearAdminSession,
  readAdminSession,
  writeAdminSession,
} from "@/lib/auth-session";
import { AUTH_LOGIN_PATH } from "@/lib/auth-routes";

function subscribe(callback: () => void) {
  if (typeof window === "undefined") return () => {};
  const onStorage = (e: StorageEvent) => {
    if (e.key === null || e.key === ADMIN_SESSION_KEY) callback();
  };
  const onCustom = () => callback();
  window.addEventListener("storage", onStorage);
  window.addEventListener(ADMIN_SESSION_EVENT, onCustom);
  return () => {
    window.removeEventListener("storage", onStorage);
    window.removeEventListener(ADMIN_SESSION_EVENT, onCustom);
  };
}

function getSessionSnapshot(): AuthUser | null {
  return readAdminSession();
}

function getServerSnapshot(): null {
  return null;
}

export type StaffLoginResult =
  | "success"
  | "invalid_credentials"
  | "staff_only";

type AuthContextValue = {
  user: AuthUser | null;
  login: (email: string, password: string) => Promise<StaffLoginResult>;
  loginDevelopment: (userId: string) => Promise<StaffLoginResult>;
  loginGoogle: (credential: string) => Promise<StaffLoginResult>;
  logout: () => void;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const router = useRouter();
  const user = useSyncExternalStore(
    subscribe,
    getSessionSnapshot,
    getServerSnapshot,
  );

  const login = useCallback(async (email: string, password: string) => {
    let u: AuthUser;
    try {
      const payload = await loginWithEmail({
        email: email.trim(),
        password,
      });
      u = toAdminSessionUser(payload);
    } catch {
      return "invalid_credentials";
    }
    if (!canAccessStaffAdmin(u)) return "staff_only";
    writeAdminSession(u);
    window.dispatchEvent(new Event(ADMIN_SESSION_EVENT));
    return "success";
  }, []);

  const loginDevelopment = useCallback(async (userId: string) => {
    let u: AuthUser;
    try {
      const payload = await loginWithDevelopmentUser({
        userId: userId.trim(),
      });
      u = toAdminSessionUser(payload);
    } catch {
      return "invalid_credentials";
    }
    if (!canAccessStaffAdmin(u)) return "staff_only";
    writeAdminSession(u);
    window.dispatchEvent(new Event(ADMIN_SESSION_EVENT));
    return "success";
  }, []);

  const loginGoogle = useCallback(async (credential: string) => {
    let u: AuthUser;
    try {
      const payload = await loginWithGoogle(credential);
      u = toAdminSessionUser(payload);
    } catch {
      return "invalid_credentials";
    }
    if (!canAccessStaffAdmin(u)) return "staff_only";
    writeAdminSession(u);
    window.dispatchEvent(new Event(ADMIN_SESSION_EVENT));
    return "success";
  }, []);

  const logout = useCallback(() => {
    clearAdminSession();
    window.dispatchEvent(new Event(ADMIN_SESSION_EVENT));
    router.replace(AUTH_LOGIN_PATH);
  }, [router]);

  const value = useMemo(
    () => ({ user, login, loginDevelopment, loginGoogle, logout }),
    [user, login, loginDevelopment, loginGoogle, logout],
  );

  return (
    <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
  );
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth phải dùng bên trong AuthProvider");
  }
  return ctx;
}

const noopSubscribe = () => () => {};

/** Tránh flash / hydration: server `false`, client `true` (không dùng setState trong effect). */
export function useClientReady(): boolean {
  return useSyncExternalStore(noopSubscribe, () => true, () => false);
}

src/providers/backend-admin-layout.tsx.content:
"use client"

import { useMemo, type ReactNode } from "react"
import {
  ADMIN_PUBLIC_BRANDING_QUERY_KEY,
  ADMIN_PUBLIC_SITE_SEO_QUERY_KEY,
  ADMIN_SITE_SEO_PAGE_KEY,
  AdminLayoutBridge,
  buildAdminLayoutValue,
  useAdminDocumentHeadOverride,
  useAdminDocumentTitle,
  useAdminPublicSiteSeo,
  useAdminSiteBranding,
} from "@ui/components/admin"
import { api } from "@/lib/api"
import { BACKEND_ADMIN_LAYOUT_STATIC } from "@/config/admin-layout-static"
import { AdminRealtimeSync } from "@/providers/admin-realtime-sync"
import { useAuth, useClientReady } from "@/providers/auth-provider"

export function BackendAdminLayoutProvider({ children }: { children: ReactNode }) {
  const clientReady = useClientReady()
  const { user, logout } = useAuth()

  const branding = useAdminSiteBranding({
    queryKey: ADMIN_PUBLIC_BRANDING_QUERY_KEY,
    fetchBranding: ({ signal }) =>
      api.settings.getPublicBranding({ signal }),
  })

  const siteSeo = useAdminPublicSiteSeo({
    queryKey: ADMIN_PUBLIC_SITE_SEO_QUERY_KEY,
    page: ADMIN_SITE_SEO_PAGE_KEY,
    fetchSiteSeo: ({ signal, page }) =>
      api.seoMetas.getPublicByPage(page, { signal }),
  })

  const documentHeadOverride = useAdminDocumentHeadOverride()

  useAdminDocumentTitle({
    siteName: documentHeadOverride?.siteName ?? branding.siteName,
    siteDescription:
      documentHeadOverride?.siteDescription ?? branding.siteDescription,
    metaTitle:
      documentHeadOverride?.metaTitle ??
      (siteSeo.isReady ? siteSeo.data?.title : undefined),
    metaDescription:
      documentHeadOverride?.metaDescription ??
      (siteSeo.isReady ? siteSeo.data?.description : undefined),
    titleFallback: "Quản trị",
    descriptionFallback: "Quản trị hệ thống",
  })

  const value = useMemo(
    () =>
      buildAdminLayoutValue({
        user: user ?? null,
        clientReady,
        logout,
        branding,
        static: BACKEND_ADMIN_LAYOUT_STATIC,
      }),
    [branding, clientReady, logout, user],
  )

  return (
    <AdminLayoutBridge value={value}>
      <AdminRealtimeSync />
      {children}
    </AdminLayoutBridge>
  )
}

src/providers/query-provider.tsx.content:
"use client";

import { useState } from "react";
import { QueryClientProvider } from "@tanstack/react-query";
import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
import {
  createHubQueryClient,
  hubAdminQueryClientDefaultOptions,
} from "@workspace/query-client";
import { createAdminMutationCache } from "@/hooks/use-admin-mutation";

export function QueryProvider({ children }: { children: React.ReactNode }) {
  const [client] = useState(() =>
    createHubQueryClient({
      mutationCache: createAdminMutationCache(),
      defaultOptions: hubAdminQueryClientDefaultOptions,
    }),
  );

  return (
    <QueryClientProvider client={client}>
      {children}
      {process.env.NODE_ENV === "development" && (
        <ReactQueryDevtools initialIsOpen={false} buttonPosition="bottom-left" />
      )}
    </QueryClientProvider>
  );
}

